-- ---------------------------------------------------------------------------
-- 1. Helper: next_billing_date_after(d, period)
--    Returns the first billing date strictly after `d` for the given period.
--    IMMUTABLE — safe to index over and use in generated columns.
--
--    Note for Member 3: The billing job MUST use this function to advance
--    subscriptions.next_billing_date upon successful invoice creation, so that
--    every team member and database trigger computes periods identically.
-- ---------------------------------------------------------------------------
create or replace function public.next_billing_date_after(
  d      date,
  period text
)
returns date
language plpgsql
immutable
parallel safe
as $$
begin
  case period
    when 'daily' then
      return d + 1;
    when 'weekly' then
      return d + 7;
    when 'monthly' then
      -- Postgres date + interval '1 month' correctly clamps month-ends (e.g. Jan 31 -> Feb 28/29)
      return (d + interval '1 month')::date;
    when 'yearly' then
      -- Postgres date + interval '1 year' clamps Feb 29 to Feb 28 in non-leap years
      return (d + interval '1 year')::date;
    else
      raise exception 'unknown billing period: %', period;
  end case;
end;
$$;

comment on function public.next_billing_date_after(date, text) is
  'Returns the next billing date after d for the given billing period (daily/weekly/monthly/yearly).
   Month and year additions correctly clamp to the end of shorter months (e.g., Jan 31 + 1 month = Feb 28/29).
   Raises an error for unknown periods.
   The recurring billing job should use this function to advance next_billing_date, ensuring consistent date arithmetic across all modules.';

-- ---------------------------------------------------------------------------
-- 2. View: billable_subscriptions
--    Shows every active subscription due for billing today or overdue,
--    where next_billing_date <= current_date and within expiry_date.
--    security_invoker = true ensures row-level security (RLS) on subscriptions applies.
--
--    Columns:
--      subscription_id, id, number, customer_id, customer_name, customer_email,
--      plan_id, plan_name, billing_period, payment_terms, start_date, expiry_date,
--      next_billing_date, period_start, period_end, lines, subtotal, tax_total, total_amount
-- ---------------------------------------------------------------------------
create or replace view public.billable_subscriptions
with (security_invoker = true)
as
select
  -- Subscription identifiers
  s.id                                                                     as subscription_id,
  s.id                                                                     as id,
  s.number,
  s.customer_id,
  pr.full_name                                                             as customer_name,
  pr.email                                                                 as customer_email,
  s.plan_id,
  p.name                                                                   as plan_name,
  p.billing_period,
  s.payment_terms,
  s.start_date,
  s.expiry_date,
  s.next_billing_date,
  s.status,
  s.created_at,
  s.updated_at,

  -- Billing cycle interval
  s.next_billing_date                                                      as period_start,
  (public.next_billing_date_after(s.next_billing_date, p.billing_period) - 1)::date as period_end,

  -- Itemized lines snapshot as JSONB array
  agg.lines,

  -- Pre-aggregated financial totals
  agg.subtotal,
  agg.tax_total,
  agg.total_amount

from public.subscriptions s
join public.plans p on p.id = s.plan_id
left join public.profiles pr on pr.id = s.customer_id

-- Subquery / Lateral join aggregating lines so each subscription appears exactly once
cross join lateral (
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'line_id',      sl.id,
          'product_id',   sl.product_id,
          'product_name', prod.name,
          'variant_id',   sl.variant_id,
          'quantity',     sl.quantity,
          'unit_price',   sl.unit_price,
          'tax_id',       sl.tax_id,
          'amount',       sl.amount
        )
        order by sl.created_at
      ),
      '[]'::jsonb
    )                             as lines,
    coalesce(sum(sl.amount), 0)   as subtotal,
    0::numeric(12, 2)             as tax_total,
    coalesce(sum(sl.amount), 0)   as total_amount
  from public.subscription_lines sl
  left join public.products prod on prod.id = sl.product_id
  where sl.subscription_id = s.id
) agg

where
  s.status = 'active'
  and s.next_billing_date is not null
  and s.next_billing_date <= current_date
  and s.next_billing_date <= s.expiry_date;

comment on view public.billable_subscriptions is
  'Active subscriptions due for billing today or overdue (next_billing_date <= CURRENT_DATE
   and within expiry_date). tax_total is 0 — Member 3 billing engine applies tax_rules.
   Each subscription appears exactly once (lateral join, no fan-out).
   Secured via security_invoker=true; RLS on subscriptions table applies.';

-- ---------------------------------------------------------------------------
-- 3. Grants
-- ---------------------------------------------------------------------------
grant select on public.billable_subscriptions to authenticated;
